const TMDB_API_KEY = "b56be59cfcfc26fbad50e51fb6341736"; // 🔑 실제 TMDB API 키를 입력하세요.
const BASE_URL = "https://api.themoviedb.org/3";
const IMAGE_BASE_URL = "https://image.tmdb.org/t/p/w780";

/**
 * TMDB에서 영화의 Credits(제작진) 정보를 가져오는 내부 함수
 * @param {number} tmdbMovieId - TMDB 영화 ID
 * @returns {object|null} 감독 정보가 포함된 Credits 객체
 */
const getCreditsFromTMDB = async (tmdbMovieId) => {
  try {
    const response = await axios.get(`${BASE_URL}/movie/${tmdbMovieId}/credits`, {
      params: { api_key: TMDB_API_KEY },
    });
    return response.data;
  } catch (error) {
    console.error(`TMDB Credits 요청 오류 (ID: ${tmdbMovieId}):`, error.message);
    return null;
  }
};

/**
 * TMDB에서 정확한 영화 포스터를 가져오는 고도화된 함수
 * @param {string} title - KOFIC 제공 영화 제목 (국문)
 * @param {string} year - KOFIC 제공 개봉 연도 (YYYY)
 * @param {object} options - 추가 옵션 (directorName, movieNmEn 등)
 * @returns {string|null} 포스터 URL 또는 null
 */
export const getPosterFromTMDB = async (title, year, options = {}) => {
  try {
    // 1. 제목과 개봉연도로 TMDB에서 영화 목록 검색
    const searchResponse = await axios.get(`${BASE_URL}/search/movie`, {
      params: {
        api_key: TMDB_API_KEY,
        query: title,
        language: "ko-KR",
        primary_release_year: year,
        include_adult: false,
      },
    });

    const results = searchResponse.data.results;
    if (!results || results.length === 0) {
      // 검색 결과가 없으면 영문 제목으로 재시도
      if (options.movieNmEn) {
        return getPosterFromTMDB(options.movieNmEn, year, { ...options, movieNmEn: null }); // 무한 재귀 방지
      }
      return null;
    }

    // --- 정확한 영화를 찾기 위한 매칭 시작 ---

    // 2. 감독 이름으로 정확히 일치하는 영화 찾기 (가장 우선순위 높음)
    if (options.directorName) {
      for (const movie of results) {
        const credits = await getCreditsFromTMDB(movie.id);
        const director = credits?.crew.find(person => person.job === 'Director');

        // KOFIC 감독 이름과 TMDB 감독 이름이 일치하는지 확인
        if (director && director.name === options.directorName) {
          console.log(`✅ [감독 일치] ${title}:`, movie);
          return movie.poster_path ? `${IMAGE_BASE_URL}${movie.poster_path}` : null;
        }
      }
    }

    // 3. 감독으로 못찾았을 경우, KOFIC 영문 제목과 TMDB 원제를 비교
    if (options.movieNmEn) {
        const englishMatch = results.find(
            (movie) => movie.original_title.toLowerCase() === options.movieNmEn.toLowerCase()
        );
        if (englishMatch) {
            console.log(`✅ [영문 제목 일치] ${title}:`, englishMatch);
            return englishMatch.poster_path ? `${IMAGE_BASE_URL}${englishMatch.poster_path}` : null;
        }
    }
    
    // 4. 최후의 수단: 검색 결과가 1개 뿐이고, 다른 정보가 없을 때만 사용 (신뢰도 낮음)
    //    하지만 동명 영화 문제 때문에 이 로직은 주석 처리. 명확한 근거 없이는 선택하지 않음.
    // if (results.length === 1) {
    //   console.log(`⚠️ [단일 결과 선택] ${title}:`, results[0]);
    //   return results[0].poster_path ? `${IMAGE_BASE_URL}${results[0].poster_path}` : null;
    // }

    // 매칭 실패 시, 잘못된 포스터를 보여주지 않기 위해 null 반환
    console.warn(`🚨 [매칭 실패] "${title} (${year})". 정확한 영화를 찾지 못했습니다.`);
    return null;

  } catch (error) {
    console.error(`TMDB 포스터 API 전체 오류 (${title}):`, error.message);
